import { RuleWithSource } from "../..";
import { RuleFrontmatter } from "./parseMarkdownRule";

/**
 * The file extension used for markdown rule files.
 */
export const RULE_FILE_EXTENSION = "md";

export interface CreateRuleMarkdownOptions {
  description?: RuleWithSource["description"];
  globs?: RuleWithSource["globs"];
  alwaysApply?: RuleWithSource["alwaysApply"];
}

/**
 * Sanitizes a rule name for use in a filename.
 *
 * - Converts to lowercase
 * - Removes non-alphanumeric characters except spaces and hyphens
 * - Replaces sequences of spaces with a single hyphen
 * - Trims leading/trailing dashes
 *
 * Returns an empty string for empty or whitespace-only input.
 */
export function sanitizeRuleName(ruleName: string): string {
  if (!ruleName || !ruleName.trim()) {
    return "";
  }

  return ruleName
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Constructs the file path for a rule within a workspace.
 *
 * Returns `{workspaceDir}/.continue/rules/{sanitized-name}.md`.
 */
export function createRuleFilePath(
  workspaceDir: string,
  ruleName: string,
): string {
  const safeRuleName = sanitizeRuleName(ruleName);
  const normalizedDir = workspaceDir.replace(/\/+$/, "");
  return `${normalizedDir}/.continue/rules/${safeRuleName}.${RULE_FILE_EXTENSION}`;
}

/**
 * Wraps markdown content with YAML frontmatter.
 *
 * Produces `---\n{yaml-frontmatter}\n---\n\n{markdown}`. When the frontmatter
 * is empty, the frontmatter body is `{}` so that the result remains parseable
 * by `parseMarkdownRule`.
 */
export function createMarkdownWithFrontmatter(
  frontmatter: RuleFrontmatter,
  markdown: string,
): string {
  const hasFields = frontmatter && Object.keys(frontmatter).length > 0;
  const frontmatterYaml = hasFields
    ? YAML.stringify(frontmatter).trim()
    : "{}";

  return `---\n${frontmatterYaml}\n---\n\n${markdown}`;
}

/**
 * Generates markdown for a rule with YAML frontmatter.
 *
 * The markdown body is formatted as `# {name}\n\n{ruleContent}`. Frontmatter
 * fields are only included when provided; `alwaysApply` is only included when
 * it is explicitly `false`.
 */
export function createRuleMarkdown(
  name: string,
  ruleContent: string,
  options: CreateRuleMarkdownOptions = {},
): string {
  const frontmatter: RuleFrontmatter = {};

  if (options.globs) {
    frontmatter.globs =
      typeof options.globs === "string" ? options.globs.trim() : options.globs;
  }

  if (options.description) {
    frontmatter.description = options.description.trim();
  }

  if (options.alwaysApply === false) {
    frontmatter.alwaysApply = false;
  }

  const markdown = `# ${name}\n\n${ruleContent}`;

  return createMarkdownWithFrontmatter(frontmatter, markdown);
}
