} from "../markdown/createMarkdownRule";
import { joinPathsToUri } from "../../util/uri";

function getContentsForNewBlock(blockType: BlockType): ConfigYaml {
  const configYaml: ConfigYaml = {
    name: `New ${blockType.slice(0, -1)}`,
    version: "0.0.1",
    schema: "v1",
  };
  switch (blockType) {
    case "context":
      configYaml.context = [
        {
          provider: "file",
        },
      ];
      break;
    case "models":
      configYaml.models = [
        {
          provider: "anthropic",
          model: "claude-3-7-sonnet-latest",
          apiKey: "${{ secrets.ANTHROPIC_API_KEY }}",
          name: "Claude 3.7 Sonnet",
          roles: ["chat", "edit"],
        },
      ];
      break;
    case "rules":
      configYaml.rules = ["Always give concise responses"];
      break;
    case "docs":
      configYaml.docs = [
        {
          name: "New docs",
          startUrl: "https://docs.continue.dev",
        },
      ];
      break;
    case "prompts":
      configYaml.prompts = [
        {
          name: "New prompt",
          description: "New prompt",
          prompt:
            "Please write a thorough suite of unit tests for this code, making sure to cover all relevant edge cases",
        },
      ];
      break;
    case "mcpServers":
      configYaml.mcpServers = [
        {
          name: "New MCP server",
          command: "npx",
          args: ["-y", "<your-mcp-server>"],
          env: {},
        },
      ];
      break;
  }

  return configYaml;
}

/**
 * Returns the initial file content for a newly created block.
 *
 * Rules are created as markdown files with YAML frontmatter, while all other
 * block types are serialized as YAML config.
 */
export function getFileContent(blockType: BlockType): string {
  if (blockType === "rules") {
    return createRuleMarkdown("New Rule", "Your rule content", {
      description: "A description of your rule",
    });
  }

  return YAML.stringify(getContentsForNewBlock(blockType));
}

/**
 * Maps a block type to its base filename (without extension).
 */
function getBaseFilename(blockType: BlockType): string {
  return `new-${blockType.slice(0, -1)}`;
}

/**
 * Finds the first available filename URI within `baseDirUri` for the given
 * block type, appending numeric suffixes until an unused name is found.
 */
export async function findAvailableFilename(
  baseDirUri: string,
  blockType: BlockType,
  fileExists: (fileUri: string) => Promise<boolean>,
): Promise<string> {
  const baseName = getBaseFilename(blockType);
  const extension = blockType === "rules" ? RULE_FILE_EXTENSION : "yaml";

  let counter = 0;
  let fileUri: string;
  do {
    const suffix = counter === 0 ? "" : `-${counter}`;
    fileUri = joinPathsToUri(baseDirUri, `${baseName}${suffix}.${extension}`);
    counter++;
  } while (await fileExists(fileUri));

  return fileUri;
}

export async function createNewWorkspaceBlockFile(
  ide: IDE,
  blockType: BlockType,
): Promise<void> {
  const workspaceDirs = await ide.getWorkspaceDirs();
  if (workspaceDirs.length === 0) {
    throw new Error(
      "No workspace directories found. Make sure you've opened a folder in your IDE.",
    );
  }

  const baseDirUri = joinPathsToUri(workspaceDirs[0], `.continue/${blockType}`);

  const fileUri = await findAvailableFilename(baseDirUri, blockType, (uri) =>
    ide.fileExists(uri),
  );

  await ide.writeFile(fileUri, getFileContent(blockType));
  await ide.openFile(fileUri);
}
